public class MainClassScannerTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        String plain = "public class App {\n"
                + "    public static void main(String[] args) {\n"
                + "        System.out.println(1);\n"
                + "    }\n"
                + "}\n";
        String wrapped = "public class Tool {\n"
                + "    static public void\n"
                + "            main(String[] args) {\n"
                + "    }\n"
                + "}\n";
        String varargs = "public class Flex {\n"
                + "    public static void main(String... args) {\n"
                + "    }\n"
                + "}\n";
        String commented = "public class Legacy {\n"
                + "    // public static void main(String[] args) {\n"
                + "    // }\n"
                + "}\n";
        String none = "public class Helper {\n"
                + "    static int twice(int n) { return n + n; }\n"
                + "}\n";

        check("plain main", true, MainClassScanner.isRunnable(plain));
        check("modifiers swapped and wrapped", true, MainClassScanner.isRunnable(wrapped));
        check("varargs main", true, MainClassScanner.isRunnable(varargs));
        check("commented out main", false, MainClassScanner.isRunnable(commented));
        check("no main at all", false, MainClassScanner.isRunnable(none));

        java.util.Map<String, String> sources = new java.util.LinkedHashMap<>();
        sources.put("Tool.java", wrapped);
        sources.put("App.java", plain);
        sources.put("Legacy.java", commented);
        sources.put("Helper.java", none);
        sources.put("Flex.java", varargs);
        check("runnable classes sorted", "[App, Flex, Tool]",
                MainClassScanner.findMainClasses(sources).toString());
        check("empty map", "[]",
                MainClassScanner.findMainClasses(new java.util.LinkedHashMap<String, String>()).toString());
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

