public class MainClassScanner {

    public static boolean isRunnable(String source) {
        if (source == null) {
            return false;
        }
        String cleaned = clean(source);
        return cleaned.contains("public static void main(String[]")
                || cleaned.contains("static public void main(String[]")
                || cleaned.contains("public static void main(String...");
    }

    private static String clean(String source) {
        StringBuilder text = new StringBuilder();
        for (String line : source.split("\n", -1)) {
            int comment = line.indexOf("//");
            if (comment >= 0) {
                line = line.substring(0, comment);
            }
            text.append(line).append(' ');
        }
        return text.toString().replaceAll("\\s+", " ");
    }

    public static java.util.List<String> findMainClasses(java.util.Map<String, String> sources) {
        java.util.List<String> names = new java.util.ArrayList<>();
        if (sources == null) {
            return names;
        }
        for (java.util.Map.Entry<String, String> entry : sources.entrySet()) {
            if (!isRunnable(entry.getValue())) {
                continue;
            }
            String name = entry.getKey();
            if (name.endsWith(".java")) {
                name = name.substring(0, name.length() - ".java".length());
            }
            names.add(name);
        }
        java.util.Collections.sort(names);
        return names;
    }
}
